import { Type } from 'class-transformer';
import {
  ArrayMaxSize,
  ArrayMinSize,
  IsArray,
  IsIn,
  IsISO8601,
  IsObject,
  IsOptional,
  IsString,
  IsUUID,
  Length,
  ValidateIf,
  ValidateNested,
} from 'class-validator';

export const MAX_BATCH_SIZE = 100;
export const EVENT_TYPES = ['track', 'identify'] as const;
export type EventType = (typeof EVENT_TYPES)[number];

export class EventDto {
  @IsIn(EVENT_TYPES)
  type!: EventType;

  // Generated by the SDK; makes retries idempotent.
  @IsUUID()
  messageId!: string;

  @ValidateIf((e: EventDto) => e.type === 'track')
  @IsString()
  @Length(1, 200)
  event?: string;

  // Anonymous device id before identify, user id after.
  @IsString()
  @Length(1, 200)
  distinctId!: string;

  @IsOptional()
  @IsString()
  @Length(1, 200)
  userId?: string;

  @IsOptional()
  @IsObject()
  properties?: Record<string, unknown>;

  @IsOptional()
  @IsObject()
  traits?: Record<string, unknown>;

  // SDK metadata: library version, OS, app version, locale.
  @IsOptional()
  @IsObject()
  context?: Record<string, unknown>;

  @IsISO8601({ strict: true })
  timestamp!: string;
}

export class BatchDto {
  @IsArray()
  @ArrayMinSize(1)
  @ArrayMaxSize(MAX_BATCH_SIZE)
  @ValidateNested({ each: true })
  @Type(() => EventDto)
  batch!: EventDto[];

  // Device clock when the batch was sent; used to correct clock skew.
  @IsOptional()
  @IsISO8601({ strict: true })
  sentAt?: string;
}
